// GENERATED by scripts/build-io.mjs from src/ - edit the source, not this file.
// Turning a picked file or a voice recording into what the WWC socket expects.
//
// The socket takes the file inline, as a `data:` URI in the message's `media`
// field: it decodes it, stores it and forwards the hosted `media_url` to Flows
// (pkg/websocket/helper.go in weni-ai/weni-webchat-socket). There is no upload
// endpoint to call first, which is what makes attachments possible at all from
// a single injected script with no asset host of its own.
import type { MediaKind } from './wwcClient';

/**
 * Cap on what we put on the wire. The frame travels whole over the socket and
 * base64 inflates it by a third, so this is about what a proxy will carry, not
 * about what the browser can read.
 */
export const MAX_ATTACHMENT_BYTES = 8 * 1024 * 1024;

/** What the composer offers to pick. Anything the agent can actually be sent. */
export const ACCEPTED_FILE_TYPES = 'image/*,video/*,audio/*,.pdf,.doc,.docx,.xls,.xlsx,.csv,.txt';

/** The socket's own bucket of message types, from the file's MIME type. */
export function kindOfMime(mime: string): MediaKind {
  if (mime.startsWith('image/')) return 'image';
  if (mime.startsWith('video/')) return 'video';
  if (mime.startsWith('audio/')) return 'audio';
  return 'file';
}

export function humanSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/**
 * Reads a blob as a `data:` URI, guaranteeing the `<type>/<subtype>;` prefix
 * the socket parses the file extension out of. A file the OS has no MIME type
 * for reads back as `data:;base64,…`, which would break that parse, so it is
 * relabelled rather than sent malformed.
 */
export function readAsDataUri(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(reader.error ?? new Error('read failed'));
    reader.onload = () => {
      const raw = String(reader.result ?? '');
      const comma = raw.indexOf(',');
      const header = comma > -1 ? raw.slice(5, comma) : '';
      if (header.includes('/')) {
        resolve(raw);
        return;
      }
      resolve(`data:application/octet-stream;base64,${comma > -1 ? raw.slice(comma + 1) : ''}`);
    };
    reader.readAsDataURL(blob);
  });
}
